import {
  CAR_PROTECTION,
  PROPERTY_PROTECTION,
  MARINE_CARGO,
  MARINE_CARGO_PROTECTION,
} from '../../../../../../constants/pkgCode'
import { LANG_STRINGS } from '../../../../../../lang/index'
import { POLICY_STEPS } from '../../../../Policy/constants'

export function getPageTitle(productType) {
  switch (productType) {
    case CAR_PROTECTION:
      return LANG_STRINGS.insuranceMobil
    case PROPERTY_PROTECTION:
      return LANG_STRINGS.property
    case MARINE_CARGO:
    case MARINE_CARGO_PROTECTION:
      return LANG_STRINGS.kargo
    default:
      return LANG_STRINGS.payment
  }
}

export function getStepsHeaderData(productType) {
  switch (productType) {
    case CAR_PROTECTION:
      return {
        isShow: true,
        stepsData: POLICY_STEPS,
        activeCount: 6,
        prevActive: { 1: true, 2: true, 3: true, 4: true, 5: true },
      }
    default:
      return { isShow: false }
  }
}

export const shareCustomerPaymentLinkMessage = (policy, invoiceLink) => `
  Halo ${policy?.customer_data?.name || 'Sahabat PasPol'},
  Berikut invoice untuk pembayaran polis Anda.
  Silakan cek detail invoice dan lakukan pembayaran melalui link berikut: ${invoiceLink}
`
