import { useCallback, useEffect, useMemo } from 'react'
import { useHistory, useParams } from 'react-router-dom'
import { get } from 'lodash'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Container } from '../../../../../../components'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { FLEET_POLICY, MANUAL_ORDER } from '../../../../../../constants/pkgCode'
import { sharingViaWhatsApp } from '../../../../../../helpers/sharingWA'
import { LANG_STRINGS } from '../../../../../../lang'
import { useGetOfflineQuoteDetail } from '../../../../../../state/commonState/hooks/useCommonContext'
import { useGetPolicyDetails } from '../../../state/hooks/usePaymentState'
import XenditPayment from '../../XenditPayment'
import { getPageTitle, getStepsHeaderData, shareCustomerPaymentLinkMessage } from './helpers'
import { ButtonContainer, PaymentPageStyle, PolicySummary } from './index.style'

const POLICY_SUMMARY = [
  { label: LANG_STRINGS.policyHolder1, key: 'customer_data.name' },
  { label: LANG_STRINGS.typeInsurance, key: 'product.package.product.name' },
  { label: LANG_STRINGS.agentName, key: 'agent_info.name' },
  { label: LANG_STRINGS.packageTitle, key: 'product.package.name' },
]

function PaymentPageContainer() {
  const history = useHistory()
  const { policyId, productType } = useParams()

  const [{ getPolicyDetailData }, getPolicyDetailsReq] = useGetPolicyDetails()
  const [{ offlineQuoteDetailData }, offlineQuoteDetailReq] = useGetOfflineQuoteDetail()
  const [{ GET_POLICY_DETAIL_LOADER, AGENT_PAYING_LOADER, GET_PAYMENT_URL_LOADER }] =
    useLoaderContextValue()

  const pageTitle = useMemo(() => getPageTitle(productType), [productType])
  const stepsHeaderData = useMemo(() => getStepsHeaderData(productType), [productType])

  const policy = useMemo(() => {
    if (getPolicyDetailData?.id) {
      return getPolicyDetailData
    } else if (offlineQuoteDetailData?.id) {
      return { ...offlineQuoteDetailData?.policy_details }
    }
    return {}
  }, [getPolicyDetailData, offlineQuoteDetailData])

  useEffect(() => {
    // On init, hit get policy API
    if ([MANUAL_ORDER, FLEET_POLICY].includes(productType)) {
      offlineQuoteDetailReq({ quoteId: policyId })
    } else {
      getPolicyDetailsReq({ policyId, query: { show_agent: 1 } })
    }
  }, [policyId, productType, getPolicyDetailsReq, offlineQuoteDetailReq])

  const handleClickReturn = useCallback(() => {
    history.push(`/transactions/${policyId}/details`)
  }, [history, policyId])

  const handleClickShare = useCallback(() => {
    if (!policy?.invoice_receipt_url) {
      // Invoice is generated asynchronously. If invoice is not ready, retry API call
      ShowSnackbar.error({
        text: 'Invoice anda belum siap, silahkan coba lagi setelah 30 detik.',
      })
      getPolicyDetailsReq({ policyId, query: { show_agent: 1 } })
      return
    }

    sharingViaWhatsApp({
      text: shareCustomerPaymentLinkMessage(policy, policy?.invoice_receipt_url),
    })
  }, [policy, policyId, getPolicyDetailsReq])

  return (
    <Container
      title={pageTitle}
      loader={GET_POLICY_DETAIL_LOADER || AGENT_PAYING_LOADER || GET_PAYMENT_URL_LOADER}
      hideBottomTabs
      hideGuardianInfo
      showCloseIcon
      onClose={() => history.replace('/dashboard')}
      onBackClick={handleClickReturn}
    >
      <PaymentPageStyle padTop={stepsHeaderData.isShow ? '92px' : '48px'}>
        {stepsHeaderData.isShow && (
          <PolicyStepsHeader
            stepsData={stepsHeaderData.stepsData}
            activeCount={stepsHeaderData.activeCount}
            prevActive={stepsHeaderData.prevActive}
          />
        )}
        <PolicySummary>
          <div className="application-number">{policy?.application_no}</div>
          <div className="policy-detail">
            {POLICY_SUMMARY.map((item) => (
              <div>
                <div className="label">{item.label}</div>
                <div className="data">{get(policy, item.key, '-')}</div>
              </div>
            ))}
          </div>
        </PolicySummary>
        <XenditPayment
          policy={policy}
          policyId={policyId}
          stepsHeader={stepsHeaderData.isShow}
          paymentBy="agent"
        />
        <ButtonContainer>
          <Button variant="outlined" onClick={handleClickReturn}>
            {LANG_STRINGS.return}
          </Button>
          <Button variant="filled" onClick={handleClickShare}>
            {LANG_STRINGS.share}
          </Button>
        </ButtonContainer>
      </PaymentPageStyle>
    </Container>
  )
}

export default PaymentPageContainer
